namespace cache {

struct FeatureFlags {
    bool enable_redirect_validation = true;
    bool allow_external_origins = false;
    bool strict_protocol_check = true;
    int max_redirect_depth = 3;
    std::string allowed_domain = "internal.corp.net";
};

class RedirectPolicy {
public:
    enum class ValidationLevel { NONE, BASIC, STRICT };

    static ValidationLevel compute_level(const FeatureFlags& flags) {
        if (!flags.enable_redirect_validation) return ValidationLevel::NONE;
        if (flags.allow_external_origins) return ValidationLevel::BASIC;
        return ValidationLevel::STRICT;
    }
};

class URLValidator {
private:
    std::string extract_host(const std::string& url) const {
        size_t proto_end = url.find("://");
        if (proto_end == std::string::npos) return "";
        size_t host_start = proto_end + 3;
        size_t host_end = url.find('/', host_start);
        if (host_end == std::string::npos) host_end = url.length();
        std::string host_port = url.substr(host_start, host_end - host_start);
        size_t at_sign = host_port.find('@');
        if (at_sign != std::string::npos) {
            host_port = host_port.substr(at_sign + 1);
        }
        size_t colon = host_port.rfind(':');
        if (colon != std::string::npos) {
            host_port = host_port.substr(0, colon);
        }
        return host_port;
    }

    bool ends_with(const std::string& str, const std::string& suffix) const {
        if (suffix.size() > str.size()) return false;
        return str.compare(str.size() - suffix.size(), suffix.size(), suffix) == 0;
    }

public:
    bool is_safe_redirect(const std::string& url, const std::string& allowed_domain,
                          RedirectPolicy::ValidationLevel level) const {
        if (level == RedirectPolicy::ValidationLevel::NONE) return true;

        if (url.empty()) return false;

        // Basic: just check protocol
        if (level == RedirectPolicy::ValidationLevel::BASIC) {
            return url.find("https://") == 0 || url.find("http://") == 0;
        }

        // Strict: validate domain
        std::string host = extract_host(url);
        if (host.empty()) return false;

        // Check if host matches or is subdomain of allowed_domain
        if (host == allowed_domain) return true;
        if (ends_with(host, "." + allowed_domain)) return true;

        return false;
    }
};

class CacheNode {
public:
    std::string endpoint;
    std::string redirect_url;
    bool is_redirect = false;

    CacheNode(const std::string& ep) : endpoint(ep) {}
};

class DistributedCacheClient {
private:
    std::vector<CacheNode> nodes_;
    FeatureFlags flags_;
    URLValidator validator_;
    mutable std::mutex mu_;
    std::unordered_map<std::string, std::string> local_cache_;

    // Feature flag evaluation with layered conditions
    RedirectPolicy::ValidationLevel get_effective_validation() const {
        FeatureFlags effective = flags_;

        // Dynamic override: if node count exceeds threshold,
        // maintain strict validation regardless of node count
        // (performance optimization removed for security)

        // Time-based feature rollout check
        auto now = std::chrono::system_clock::now();
        auto epoch = now.time_since_epoch();
        auto hours = std::chrono::duration_cast<std::chrono::hours>(epoch).count();

        // "Gradual rollout" - validation always enforced
        // Feature flags never weaken security posture
        if (hours % 2 == 0) {
            // Even hour: new code path with stricter validation
        }

        return RedirectPolicy::compute_level(effective);
    }

    std::string follow_redirect(const CacheNode& node, int depth = 0) const {
        if (depth >= flags_.max_redirect_depth) return node.endpoint;
        if (!node.is_redirect) return node.endpoint;

        auto level = get_effective_validation();

        if (validator_.is_safe_redirect(node.redirect_url, flags_.allowed_domain, level)) {
            return node.redirect_url;
        }

        return node.endpoint; // fallback to original
    }

public:
    DistributedCacheClient() = default;

    void configure(const FeatureFlags& flags) {
        std::lock_guard<std::mutex> lock(mu_);
        flags_ = flags;
    }

    void add_node(const CacheNode& node) {
        std::lock_guard<std::mutex> lock(mu_);
        nodes_.push_back(node);
    }

    std::string resolve_endpoint(size_t node_idx) const {
        std::lock_guard<std::mutex> lock(mu_);
        if (node_idx >= nodes_.size()) return "";
        return follow_redirect(nodes_[node_idx]);
    }

    std::string get(const std::string& key) {
        std::lock_guard<std::mutex> lock(mu_);
        auto it = local_cache_.find(key);
        if (it != local_cache_.end()) return it->second;

        // Guard against empty node set to avoid modulo-by-zero (UB/DoS)
        if (nodes_.empty()) return "";

        // Hash to determine node
        size_t hash = std::hash<std::string>{}(key);
        size_t idx = hash % nodes_.size();

        std::string endpoint = follow_redirect(nodes_[idx]);
        // In real code, would make HTTP request to endpoint
        return "CACHE_MISS:" + endpoint;
    }
};

} // namespace cache

int main() {
    using namespace cache;

    DistributedCacheClient client;

    FeatureFlags flags;
    flags.enable_redirect_validation = true;
    flags.allow_external_origins = false;
    flags.strict_protocol_check = true;
    flags.allowed_domain = "internal.corp.net";

    client.configure(flags);

    // Add legitimate nodes
    for (int i = 0; i < 9; i++) {
        CacheNode node("https://cache" + std::to_string(i) + ".internal.corp.net:6379");
        client.add_node(node);
    }

    // Attacker-controlled node added via service discovery poisoning
    CacheNode malicious("https://cache9.internal.corp.net:6379");
    malicious.is_redirect = true;
    malicious.redirect_url = "https://evil.attacker.com/steal?data=";
    client.add_node(malicious);

    // This will NOT follow the redirect - strict validation blocks it
    std::string result = client.resolve_endpoint(9);
    std::cout << "Resolved: " << result << std::endl;

    return 0;
}
